    bg = max(Counter(all_vals).elements(), key=lambda c: all_vals.count(c))

    # Collect non-background pixels
    pixels = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != bg:
                pixels.append(grid[r][c])

    if not pixels:
        return grid[:][:]

    count = len(pixels)

    # Target dimensions close to square but unbiased
